import re


_UNITS = ("B", "KiB", "MiB", "GiB", "TiB")
_SCALE = 1024
_SIZE_RE = re.compile(r"(-?\d+(?:\.\d+)?)[ \t]*(B|KiB|MiB|GiB|TiB)")


def format_size(count):
    """A byte count as text with a binary unit. See TASK.md."""
    if isinstance(count, bool) or not isinstance(count, int):
        raise TypeError("count must be an int")

    negative = count < 0
    value = abs(count)
    unit_index = 0
    while unit_index < len(_UNITS) - 1 and value >= _SCALE ** (unit_index + 1):
        unit_index += 1

    if unit_index == 0:
        result = f"{value} B"
    else:
        divisor = _SCALE ** unit_index
        # Store tenths as an integer: this gives exact half-up rounding.
        tenths = (value * 10 + divisor // 2) // divisor
        if tenths >= 10240 and unit_index < len(_UNITS) - 1:
            unit_index += 1
            divisor = _SCALE ** unit_index
            tenths = (value * 10 + divisor // 2) // divisor
        result = f"{tenths // 10}.{tenths % 10} {_UNITS[unit_index]}"

    return ("-" if negative else "") + result


def parse_size(text):
    """The byte count that a size text stands for. See TASK.md."""
    if not isinstance(text, str):
        raise ValueError("invalid size")
    match = _SIZE_RE.fullmatch(text.strip())
    if match is None:
        raise ValueError("invalid size")

    number, unit = match.groups()
    sign = -1 if number.startswith("-") else 1
    unsigned = number.lstrip("+-")
    if "." in unsigned:
        whole_text, fraction_text = unsigned.split(".")
    else:
        whole_text, fraction_text = unsigned, ""
    if unit == "B" and fraction_text:
        raise ValueError("fractional bytes are invalid")

    multiplier = _SCALE ** _UNITS.index(unit)
    if not fraction_text:
        return sign * int(whole_text) * multiplier

    denominator = 10 ** len(fraction_text)
    numerator = (int(whole_text) * denominator + int(fraction_text)) * multiplier
    if numerator % denominator:
        raise ValueError("size is not a whole number of bytes")
    return sign * (numerator // denominator)
